import java.io.Closeable
class Trace : Closeable {
    override fun close() { println("close") }
}
fun main() {
    try {
        Trace().use {
            println("body")
            throw IllegalArgumentException("stop")
        }
    } catch (error: IllegalArgumentException) {
        println("caught")
    }
}

fun main() {
    val order = compareBy<String> { it.length }.thenBy { it }
    val words = listOf("cat", "ant", "ox")
    println(words.sortedWith(order.reversed()))
}

